# SEO content for tool pages, batch B.
C = {}

C['background-remover'] = dict(
guide='''<h2>How to remove a background from a photo</h2>
<ol><li><b>Upload a photo.</b> It never leaves your device.</li><li><b>Pick quality:</b> "Fast" for people and portraits (26 MB model), "Best" for any object like products, pets and cars (220 MB model).</li><li><b>Remove background,</b> then choose transparent, white, black, a brand colour or a blurred version of the original.</li><li><b>Download PNG</b> to keep transparency, or JPG with a background colour.</li></ol>
<h2>Popular uses</h2>
<ul><li><b>YouTube thumbnails:</b> cut yourself out and place yourself over a bold background, then add text with <a href="thumbnail-text.html">Thumbnail Text</a>.</li><li><b>Product photos</b> for Amazon, Meesho, Flipkart and Instagram shops on a clean white background.</li><li><b>Profile pictures</b> and LinkedIn photos.</li><li><b>Stickers and memes.</b></li></ul>
<h2>Tips for clean edges</h2>
<ul><li>Use a photo where the subject is in focus and well lit.</li><li>Choose "Best" for hair, fur and objects with holes.</li><li>Avoid backgrounds the same colour as the subject.</li></ul>
<h2>हिंदी में</h2>
<p>Photo daaliye aur ek click mein background hataiye. Transparent PNG download kijiye ya naya colour lagaiye. Thumbnail, product photo aur profile picture ke liye perfect, aur bilkul free.</p>''',
faq=[('Is it really free with no watermark?', 'Yes. There are no credits, no sign-up and no watermark, because the AI runs on your device.'),
('Can I remove backgrounds on my phone?', 'Yes. Choose the Fast model on phones; the Best model is large and works better on a computer.')])

C['script-timer'] = dict(
guide='''<h2>How long will my script take?</h2>
<p>Paste your script and pick a speaking pace. You get the total duration, a timestamp for every paragraph and how many words you need for your target length. Most people speak about 130–160 words per minute on camera; fast Shorts creators go 170+.</p>
<h2>Quick reference</h2>
<ul><li><b>30-second Short or Reel:</b> about 70–85 words.</li><li><b>60-second Short:</b> about 140–160 words.</li><li><b>8-minute YouTube video:</b> about 1,100–1,250 words.</li><li><b>10-minute video:</b> about 1,400–1,600 words.</li></ul>
<h2>Tips</h2>
<ul><li>Time the hook separately: the first 3 seconds decide if people stay.</li><li>Use paragraph timestamps to plan B-roll and to make <a href="youtube-chapters.html">YouTube chapters</a>.</li><li>Practise with the <a href="teleprompter.html">Teleprompter</a> at the same pace.</li></ul>
<h2>हिंदी में</h2>
<p>Script paste kijiye aur jaaniye video kitni lambi hogi. 60 second ki Reel ke liye lagbhag 140–160 shabd kaafi hote hain.</p>''',
faq=[('How many words is a 1-minute video?', 'About 130 to 160 words at a normal speaking pace.'),
('Does it work for Hindi scripts?', 'Yes. It counts words in any language; Hindi speakers often speak slightly faster, so try the faster pace.')])

C['title-preview'] = dict(
guide='''<h2>Why preview your YouTube title?</h2>
<p>YouTube cuts long titles with "…" in different places on the home feed, search, suggested videos and the phone app. If your key words are hidden, fewer people click. This tool shows your title and thumbnail exactly where viewers will see them, in light and dark mode.</p>
<h2>Title tips that raise click-through</h2>
<ul><li><b>Put the important words first;</b> mobile shows roughly the first 40–50 characters.</li><li><b>Keep it under 60 characters</b> where you can.</li><li><b>Match the thumbnail:</b> the title and image should tell one story, not repeat each other.</li><li><b>Use numbers and specifics:</b> "I tried 7 free AI tools" beats "Trying AI tools".</li><li>Check capitalisation with the <a href="case-converter.html">Case Converter</a>.</li></ul>
<h2>हिंदी में</h2>
<p>Upload se pehle dekhiye ki aapka title mobile aur search mein kahan kat jaata hai. Zaroori shabd shuru mein rakhiye.</p>''',
faq=[('How long should a YouTube title be?', 'Up to 100 characters are allowed, but around 60 or fewer shows fully in most places.')])

C['image-resizer'] = dict(
guide='''<h2>How to resize an image for YouTube or Instagram</h2>
<ol><li><b>Upload your image.</b></li><li><b>Pick a preset:</b> YouTube thumbnail (1280×720), channel banner (2560×1440), profile picture, Instagram square (1080×1080), portrait (1080×1350), X or LinkedIn, or a custom size.</li><li><b>Set a KB target</b> if a site has a file-size limit, and choose JPG, WebP or PNG.</li><li><b>Download.</b></li></ol>
<h2>Correct sizes</h2>
<ul><li><b>YouTube thumbnail:</b> 1280×720, under 2 MB.</li><li><b>Instagram portrait post:</b> 1080×1350 (shows biggest in the feed).</li><li><b>Reels and Shorts cover:</b> 1080×1920.</li><li><b>Government and exam forms</b> often need photos under 50–200 KB: use the KB target.</li></ul>
<h2>हिंदी में</h2>
<p>Photo ko YouTube thumbnail, Instagram post ya kisi bhi size mein badliye, aur KB limit ke andar compress kijiye. Form bharne ke liye bhi kaam aata hai.</p>''',
faq=[('Can I compress a photo to under 50 KB?', 'Yes. Set the KB target and the tool lowers quality and size until the file fits.'),
('Is my photo uploaded?', 'No. Resizing happens in your browser.')])

C['word-counter'] = dict(
guide='''<h2>Check every platform limit at once</h2>
<p>Type or paste your text and see words, characters, sentences and reading time, plus live checks against YouTube titles and descriptions, Instagram captions, TikTok, X, LinkedIn and Threads limits.</p>
<h2>Limits worth remembering</h2>
<ul><li><b>YouTube title:</b> 100 characters (about 60 show fully).</li><li><b>YouTube description:</b> 5,000 characters.</li><li><b>Instagram caption:</b> 2,200 characters and up to 30 hashtags.</li><li><b>X post:</b> 280 characters on a free account.</li></ul>
<h2>Tips</h2>
<ul><li>Front-load the first 125 characters of an Instagram caption; the rest hides behind "more". Preview it with the <a href="caption-formatter.html">Caption Formatter</a>.</li><li>Use reading time to estimate video length, or open the <a href="script-timer.html">Script Timer</a>.</li></ul>''',
faq=[('Does it count Hindi words correctly?', 'Yes. Words in Devanagari and English letters are both counted.')])

C['safe-zones'] = dict(
guide='''<h2>What is a safe zone?</h2>
<p>On Reels, Shorts and TikTok, the like, comment and share buttons sit on the right, and the caption and username sit at the bottom. Anything you put there gets covered. The safe zone is the area that stays clear on every app.</p>
<h2>How to use the checker</h2>
<ol><li>Upload your vertical video or cover image (9:16).</li><li>Switch between TikTok, Reels and Shorts to see what each app covers.</li><li>Move text and faces into the clear area before posting.</li></ol>
<h2>Rules of thumb</h2>
<ul><li>Keep important text in the middle, away from the bottom 20% and the right edge.</li><li>Captions work best in the lower-middle area; set this in <a href="auto-captions.html">Auto Captions</a>.</li><li>Check your cover image too; the grid crops it to 3:4 on Instagram.</li></ul>''',
faq=[('Are safe zones the same on every app?', 'No. TikTok covers more of the bottom than Reels or Shorts, which is why the checker shows each one.')])

C['frame-extractor'] = dict(
guide='''<h2>How to get a frame from a video</h2>
<ol><li>Upload a video.</li><li>Choose every few seconds or a set number of frames, the format (JPG, PNG or WebP) and the size.</li><li>Save the frame you want, or download them all as a ZIP.</li></ol>
<h2>Uses</h2>
<ul><li><b>Thumbnails:</b> find your best expression, then remove the background with the <a href="background-remover.html">Background Remover</a>.</li><li><b>Storyboards</b> and B-roll reference.</li><li><b>Sharp stills</b> from action clips, sports or pets.</li></ul>
<h2>Tip</h2><p>PNG keeps full quality; JPG is smaller for sharing.</p>''',
faq=[('Will the frame be blurry?', 'Frames are taken at the video\'s original resolution. Fast motion can still blur in the video itself, so extract several frames and pick the sharpest.')])

C['caption-formatter'] = dict(
guide='''<h2>Why Instagram removes your line breaks</h2>
<p>Instagram often joins lines together or deletes blank lines, turning a neat caption into one big block. The formatter adds invisible spacing so your line breaks stay exactly where you put them.</p>
<h2>How to use it</h2>
<ol><li>Write or paste your caption.</li><li>Optionally move hashtags to the end and remove duplicates.</li><li>Check the "… more" preview and the 2,200-character and 30-hashtag limits.</li><li>Copy and paste into Instagram.</li></ol>
<h2>Caption formula that works</h2>
<ul><li><b>Line 1:</b> a hook (this shows before "more").</li><li><b>Body:</b> 2–4 short lines of value.</li><li><b>Call to action:</b> "Save this" or "Comment TOOLS".</li><li><b>Hashtags</b> at the end; get a balanced set from the <a href="hashtag-generator.html">Hashtag Generator</a>.</li></ul>''',
faq=[('Does it work for Facebook and LinkedIn?', 'Yes, the line breaks also hold when pasted into most apps.')])

C['youtube-chapters'] = dict(
guide='''<h2>YouTube's chapter rules</h2>
<ul><li>The first timestamp must be <b>0:00</b>.</li><li>At least <b>3 chapters</b>.</li><li>Each chapter at least <b>10 seconds</b> long.</li><li>Timestamps go in the description, in order, one per line.</li></ul>
<p>If any rule breaks, YouTube silently ignores all your chapters. This tool builds timestamps that follow the rules, or checks the ones you already have.</p>
<h2>Why chapters help</h2>
<ul><li>Viewers jump to what they want instead of leaving.</li><li>Chapters can appear in Google search results as "key moments".</li><li>They make long tutorials easier to rewatch.</li></ul>
<h2>Tip</h2><p>Get paragraph timings from the <a href="script-timer.html">Script Timer</a>, then turn them into chapters here.</p>''',
faq=[('Why are my chapters not showing?', 'Usually the first timestamp is not 0:00, there are fewer than three, or one is shorter than 10 seconds. Paste them into the checker to see which rule fails.')])

C['srt-subtitles'] = dict(
guide='''<h2>Make an SRT file from your script</h2>
<p>Paste your script and the tool splits it into subtitle lines with timing based on speaking speed, then downloads a standard .srt file for YouTube, Premiere, DaVinci Resolve, CapCut and VLC.</p>
<h2>Fix subtitles that are out of sync</h2>
<p>Load an SRT file and shift every line earlier or later by any number of seconds in one go.</p>
<h2>Tips</h2>
<ul><li>For exact word timing from audio, use <a href="auto-captions.html">Auto Captions</a> and download its SRT.</li><li>Keep lines under about 42 characters so they fit on screen.</li><li>Add English subtitles to Hindi videos to reach a wider audience.</li></ul>''',
faq=[('What is an SRT file?', 'A plain text subtitle file with numbered lines, start and end times, and the text. Almost every video platform and editor accepts it.')])

C['case-converter'] = dict(
guide='''<h2>Which case should I use?</h2>
<ul><li><b>Title Case</b> for YouTube titles and headings.</li><li><b>Sentence case</b> for captions and descriptions; it reads more naturally.</li><li><b>UPPERCASE</b> for one or two words of emphasis in thumbnails.</li><li><b>camelCase and snake_case</b> for code, file names and URLs.</li></ul>
<h2>How to use it</h2><p>Paste your text once and switch between cases in one tap, then copy. Text written in all caps is converted properly too.</p>''',
faq=[('Does it change Hindi text?', 'Devanagari has no upper and lower case, so Hindi words stay as they are while English words convert.')])

C['qr-code'] = dict(
guide='''<h2>Make a QR code that never expires</h2>
<ol><li>Choose link, text or WiFi.</li><li>Pick colours, size and error correction (higher survives logos and wear).</li><li>Download PNG for social media or SVG for print.</li></ol>
<p>Many "free" QR sites create a redirect link that stops working after a trial. These codes contain your link directly, so they work forever, with no tracking.</p>
<h2>Ideas for creators and shops</h2>
<ul><li>A QR on your shop counter linking to Instagram or Google reviews.</li><li>WiFi QR for cafés and offices.</li><li>QR on visiting cards and event posters linking to your YouTube channel.</li></ul>''',
faq=[('Can I use it for UPI payments?', 'You can encode any text, but for UPI it is best to use the official QR from your bank or payment app.')])

