C['motion-prompts'] = dict(
guide='''<h2>What are motion prompts?</h2>
<p>A motion prompt is a detailed instruction you paste into an AI like Claude or ChatGPT. It writes a small web page that plays the animation, which you can screen record and use in Reels, Shorts, ads and presentations, without After Effects.</p>
<h2>Tips for better results</h2><ul><li>Ask for changes in plain words: "make it 9:16", "use my brand colours #E5157A and #1F4D3A", "change the text to …".</li><li>Ask for a slower or faster version if the timing feels off.</li><li>Record at 60 fps for the smoothest result.</li></ul>''',
faq=[('Do I need to know coding?', 'No. You only copy the prompt, paste the reply into a file ending in .html, and open it in your browser.')])
